create type public.twitter_analytics_attempt_status as enum('claimed','succeeded','failed','outcome_unknown');
create table public.twitter_analytics_attempts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,item_id uuid not null references public.twitter_analytics_items(id) on delete restrict,attempt_number integer not null,worker_id text not null,status public.twitter_analytics_attempt_status not null default 'claimed',idempotency_key text not null unique,http_status integer,provider_code text,request_id text,error_message text,evidence jsonb not null default '{}',started_at timestamptz not null default timezone('utc',now()),finished_at timestamptz,unique(item_id,attempt_number));
create table public.twitter_analytics_result_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,item_id uuid not null references public.twitter_analytics_items(id) on delete restrict,attempt_id uuid not null references public.twitter_analytics_attempts(id) on delete restrict,resolution text not null check(resolution in('succeeded','failed','outcome_unknown')),amount_micros bigint not null,idempotency_key text not null unique,evidence jsonb not null default '{}',created_at timestamptz not null default timezone('utc',now()));
create trigger twitter_analytics_result_immutable before update or delete on public.twitter_analytics_result_events for each row execute function public.prevent_twitter_immutable_mutation();
create unique index twitter_analytics_one_profile_claim on public.twitter_analytics_items(profile_id)where status='processing';

create or replace function public.twitter_claim_analytics_items(p_worker_id text,p_limit integer)returns table(item_id uuid,attempt_id uuid,organization_id uuid,job_id uuid,resource_type public.twitter_analytics_resource_type,resource_id uuid,profile_id uuid,connection_id uuid,zernio_post_id text,amount_micros bigint)language plpgsql security definer set search_path=public as $$begin if coalesce(auth.role(),'')<>'service_role'then raise exception using errcode='42501';end if;return query with candidates as(select i.id from public.twitter_analytics_items i where i.status='reserved'and not exists(select 1 from public.twitter_analytics_items a where a.profile_id=i.profile_id and a.status='processing')order by i.created_at,i.id for update skip locked limit least(greatest(p_limit,1),50)),updated as(update public.twitter_analytics_items i set status='processing',claimed_at=timezone('utc',now()),claimed_by=p_worker_id,attempt_count=attempt_count+1 from candidates c where i.id=c.id returning i.*),attempts(attempt_id_value,attempt_item_id)as(insert into public.twitter_analytics_attempts(organization_id,item_id,attempt_number,worker_id,idempotency_key)select u.organization_id,u.id,u.attempt_count,p_worker_id,'analytics-attempt:'||u.id||':'||u.attempt_count from updated u returning public.twitter_analytics_attempts.id,public.twitter_analytics_attempts.item_id)update public.twitter_analytics_jobs j set status='processing',started_at=coalesce(j.started_at,timezone('utc',now()))from updated u where j.id=u.job_id returning u.id,(select attempts.attempt_id_value from attempts where attempts.attempt_item_id=u.id),u.organization_id,u.job_id,u.resource_type,case when u.resource_type='post'then u.publication_item_id else u.profile_id end,u.profile_id,u.connection_id,u.zernio_post_id,u.amount_micros;end$$;

create or replace function public.twitter_complete_analytics_item(p_attempt_id uuid,p_resolution text,p_idempotency_key text,p_metrics jsonb default '{}',p_provider_updated_at timestamptz default null,p_http_status integer default null,p_provider_code text default null,p_request_id text default null,p_message text default null,p_evidence jsonb default '{}')returns jsonb language plpgsql security definer set search_path=public as $$
declare a public.twitter_analytics_attempts;i public.twitter_analytics_items;r public.twitter_wallet_reservations;released bigint:=0;settled bigint:=0;
begin if coalesce(auth.role(),'')<>'service_role'then raise exception using errcode='42501';end if;if p_resolution not in('succeeded','failed','outcome_unknown')then raise exception using errcode='22023';end if;if exists(select 1 from public.twitter_analytics_result_events where idempotency_key=p_idempotency_key)then return jsonb_build_object('idempotentReplay',true);end if;
select * into a from public.twitter_analytics_attempts where id=p_attempt_id for update;if not found then raise exception using errcode='P0002';end if;select * into i from public.twitter_analytics_items where id=a.item_id for update;if i.status in('succeeded','failed','cancelled')then raise exception using errcode='55000',message='Item de analytics já possui resultado terminal.';end if;select wr.* into r from public.twitter_analytics_job_reservations jr join public.twitter_wallet_reservations wr on wr.id=jr.reservation_id where jr.job_id=i.job_id and jr.identity_id=i.identity_id and jr.category=i.category for update;
if p_resolution='succeeded'then perform public.twitter_settle_wallet_reservation(r.id,i.amount_micros,p_idempotency_key||':debit',jsonb_build_object('analyticsItemId',i.id,'attemptId',a.id));settled:=i.amount_micros;insert into public.twitter_analytics_snapshots(organization_id,analytics_item_id,resource_type,profile_id,publication_item_id,metrics,provider_updated_at)values(i.organization_id,i.id,i.resource_type,i.profile_id,i.publication_item_id,coalesce(p_metrics,'{}'),p_provider_updated_at);update public.twitter_analytics_items set status='succeeded',result_code=p_provider_code,error_message=null where id=i.id;update public.twitter_analytics_attempts set status='succeeded',finished_at=timezone('utc',now())where id=a.id;
elsif p_resolution='failed'then update public.twitter_wallet_reservations set remaining_micros=remaining_micros-i.amount_micros,released_micros=released_micros+i.amount_micros,status=case when remaining_micros-i.amount_micros=0 then'released'::public.twitter_reservation_status else'partially_settled'::public.twitter_reservation_status end,resolved_at=case when remaining_micros-i.amount_micros=0 then timezone('utc',now())else resolved_at end where id=r.id;update public.twitter_wallets set reserved_micros=reserved_micros-i.amount_micros,version=version+1 where identity_id=r.identity_id;insert into public.twitter_reservation_events(reservation_id,organization_id,event_type,amount_micros,idempotency_key,reason,metadata)values(r.id,i.organization_id,'released',i.amount_micros,p_idempotency_key||':release',p_message,jsonb_build_object('analyticsItemId',i.id));released:=i.amount_micros;update public.twitter_analytics_items set status='failed',result_code=p_provider_code,error_message=left(p_message,1000)where id=i.id;update public.twitter_analytics_attempts set status='failed',finished_at=timezone('utc',now())where id=a.id;
else update public.twitter_analytics_items set status='outcome_unknown',result_code=p_provider_code,error_message=left(p_message,1000)where id=i.id;update public.twitter_analytics_attempts set status='outcome_unknown',finished_at=timezone('utc',now())where id=a.id;end if;
update public.twitter_analytics_attempts set http_status=p_http_status,provider_code=p_provider_code,request_id=p_request_id,error_message=left(p_message,1000),evidence=coalesce(p_evidence,'{}')where id=a.id;insert into public.twitter_analytics_result_events(organization_id,item_id,attempt_id,resolution,amount_micros,idempotency_key,evidence)values(i.organization_id,i.id,a.id,p_resolution,i.amount_micros,p_idempotency_key,coalesce(p_evidence,'{}'));
update public.twitter_analytics_jobs j set status=case when exists(select 1 from public.twitter_analytics_items x where x.job_id=j.id and x.status in('reserved','processing'))then'processing'::public.twitter_analytics_job_status when exists(select 1 from public.twitter_analytics_items x where x.job_id=j.id and x.status='outcome_unknown')then'outcome_unknown'::public.twitter_analytics_job_status when exists(select 1 from public.twitter_analytics_items x where x.job_id=j.id and x.status='succeeded')and exists(select 1 from public.twitter_analytics_items x where x.job_id=j.id and x.status in('failed','cancelled'))then'partially_succeeded'::public.twitter_analytics_job_status when not exists(select 1 from public.twitter_analytics_items x where x.job_id=j.id and x.status<>'succeeded')then'succeeded'::public.twitter_analytics_job_status else'failed'::public.twitter_analytics_job_status end,finished_at=case when not exists(select 1 from public.twitter_analytics_items x where x.job_id=j.id and x.status in('reserved','processing'))then timezone('utc',now())else null end where j.id=i.job_id;
return jsonb_build_object('itemId',i.id,'settledMicros',settled,'releasedMicros',released,'resolution',p_resolution,'idempotentReplay',false);end$$;
alter table public.twitter_analytics_attempts enable row level security;alter table public.twitter_analytics_result_events enable row level security;create policy twitter_analytics_attempts_select on public.twitter_analytics_attempts for select to authenticated using(public.is_organization_member(organization_id));create policy twitter_analytics_results_select on public.twitter_analytics_result_events for select to authenticated using(public.is_organization_member(organization_id));revoke all on table public.twitter_analytics_attempts,public.twitter_analytics_result_events from anon,authenticated;grant select on public.twitter_analytics_attempts,public.twitter_analytics_result_events to authenticated;grant all on public.twitter_analytics_attempts,public.twitter_analytics_result_events to service_role;revoke all on function public.twitter_claim_analytics_items(text,integer),public.twitter_complete_analytics_item(uuid,text,text,jsonb,timestamptz,integer,text,text,text,jsonb)from public,anon,authenticated;grant execute on function public.twitter_claim_analytics_items(text,integer),public.twitter_complete_analytics_item(uuid,text,text,jsonb,timestamptz,integer,text,text,text,jsonb)to service_role;
